import ctypes,errno,os,platform
assert platform.machine()=='x86_64'
lib=ctypes.CDLL(None,use_errno=True)
# Linux x86-64 syscall numbers, pinned by the VM architecture.
def get(pid=0):
 value=lib.syscall(252,1,int(pid))
 if value<0:raise OSError(ctypes.get_errno(),os.strerror(ctypes.get_errno()))
 return value>>13,value&8191
def set(pid,cls,data):
 if lib.syscall(251,1,int(pid),(int(cls)<<13)|int(data))<0:raise OSError(ctypes.get_errno(),os.strerror(ctypes.get_errno()))

