import pathlib,sys,time
deadline=time.monotonic()+3
while not all(pathlib.Path('ready-'+s).exists() for s in sys.argv[1:]):
 if time.monotonic()>deadline:raise RuntimeError('owned I/O-priority child not ready')
 time.sleep(.01)

